-- MAGIC ## C. Using UCX
-- MAGIC
-- MAGIC <style>
-- MAGIC table{
-- MAGIC   border-collapse: separate;
-- MAGIC   border-spacing: 0;
-- MAGIC   width: auto;
-- MAGIC   max-width: 100%;
-- MAGIC   margin: 16px 0;
-- MAGIC   float: none;
